plugins {
    id 'java'
    id 'io.quarkus' version '3.15.1'
}

repositories {
    mavenCentral()
    mavenLocal()
}

dependencies {
    implementation enforcedPlatform("io.quarkus.platform:quarkus-bom:3.15.1")
    implementation 'io.quarkus:quarkus-resteasy-reactive' // RESTEasy Reactive
    implementation 'io.quarkus:quarkus-resteasy-reactive-jackson' // RESTEasy Reactive Jackson
    implementation 'io.quarkus:quarkus-hibernate-orm-panache' // Hibernate ORM con Panache
    implementation 'io.quarkus:quarkus-hibernate-validator' // Hibernate Validator
    implementation 'io.quarkus:quarkus-flyway' // Flyway Database Migraciones
    implementation 'io.quarkus:quarkus-smallrye-openapi' // SmallRye OpenAPI & Swagger UI
    implementation 'io.quarkus:quarkus-smallrye-health' // SmallRye Health
    implementation 'io.quarkus:quarkus-micrometer-registry-prometheus' // Micrometer Prometheus
    implementation 'io.quarkus:quarkus-opentelemetry' // OpenTelemetry Tracing
    implementation 'io.quarkus:quarkus-jdbc-postgresql' // Driver JDBC PostgreSQL
    implementation 'io.quarkus:quarkus-smallrye-jwt' // SmallRye JWT RBAC

    testImplementation 'io.quarkus:quarkus-junit5'
    testImplementation 'io.rest-assured:rest-assured'
}

group 'com.example.audit'
version '1.0.0-SNAPSHOT'

java {
    sourceCompatibility = JavaVersion.VERSION_21
    targetCompatibility = JavaVersion.VERSION_21
}

test {
    systemProperty "java.util.logging.manager", "org.jboss.logmanager.LogManager"
}
compileJava {
    options.encoding = 'UTF-8'
    options.compilerArgs << '-parameters'
}

